-- =====================================================================
-- Memorepe — Bancos oficiales: examen de cívica para la ciudadanía de EE. UU. (USCIS, versión 2025)
-- 1) Inglés: 124 preguntas · 2) Español: 124 preguntas · 3) 65/20 en español: 19 preguntas
-- Fuente: USCIS M-1778 (09/25) '128 Civics Questions and Answers (2025 version)'.
-- Se excluyen las 4 preguntas cuya respuesta depende del estado (23, 29, 61, 62).
-- Correr COMPLETO una vez en el SQL Editor de Supabase. Si un banco ya existe, lo saltea.
-- =====================================================================
do $$
declare
  v_user uuid;
  v_quiz uuid;
  v_q uuid;
begin
  select id into v_user from users where username = 'memorepe';
  if v_user is null then raise exception 'No existe el usuario @memorepe'; end if;
  -- U.S. Citizenship Civics Test 2025 – Official USCIS Questions
  if not exists (select 1 from quizzes where slug = 'us-citizenship-civics-test-2025-uscis-questions') then
  values (v_user, 'U.S. Citizenship Civics Test 2025 – Official USCIS Questions', 'The official civics questions of the 2025 U.S. naturalization test (USCIS), with every accepted answer in the explanation. Includes 124 of the 128: the 4 whose answer depends on where you live (your U.S. senators, your representative, your governor and your state capital) are left out, so look them up for your state. At the interview the officer asks up to 20 questions and you must answer 12 correctly.', 'historia', 'certificacion', 'en', 'public', 'USCIS', 'Naturalization civics test', 'us-citizenship-civics-test-2025-uscis-questions', 'USCIS') returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
  else raise notice 'Ya existe: %', 'us-citizenship-civics-test-2025-uscis-questions'; end if;
  -- Examen de ciudadanía de EE. UU. 2025 – Preguntas oficiales de cívica en español
  if not exists (select 1 from quizzes where slug = 'examen-ciudadania-estados-unidos-2025-preguntas-civica-espanol') then
  values (v_user, 'Examen de ciudadanía de EE. UU. 2025 – Preguntas oficiales de cívica en español', 'Las preguntas oficiales de cívica del examen de naturalización 2025 de USCIS, traducidas al español, con todas las respuestas aceptadas y la respuesta en inglés para la entrevista. Incluye 124 de las 128: quedan afuera las 4 que dependen de dónde vives (tus senadores, tu representante, tu gobernador y la capital de tu estado). En la entrevista te hacen hasta 20 preguntas en inglés y debes acertar 12.', 'historia', 'certificacion', 'es', 'public', 'USCIS', 'Examen de cívica para la naturalización', 'examen-ciudadania-estados-unidos-2025-preguntas-civica-espanol', 'USCIS') returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
  else raise notice 'Ya existe: %', 'examen-ciudadania-estados-unidos-2025-preguntas-civica-espanol'; end if;
  -- Examen de ciudadanía de EE. UU. 65/20 – Las preguntas en español
  if not exists (select 1 from quizzes where slug = 'examen-ciudadania-estados-unidos-65-20-preguntas-espanol') then
  values (v_user, 'Examen de ciudadanía de EE. UU. 65/20 – Las preguntas en español', 'Las preguntas marcadas con asterisco del examen de cívica 2025 de USCIS, para quienes tienen 65 años o más y llevan 20 años o más como residentes permanentes. Con esta excepción puedes rendir el examen en español: te hacen 10 de estas 20 preguntas y debes acertar 6. Incluye 19: la del gobernador de tu estado depende de dónde vives.', 'historia', 'certificacion', 'es', 'public', 'USCIS', 'Examen de cívica 65/20', 'examen-ciudadania-estados-unidos-65-20-preguntas-espanol', 'USCIS') returning id into v_quiz;
  update quizzes set question_count = (select count(*) from questions where quiz_id = v_quiz) where id = v_quiz;
  else raise notice 'Ya existe: %', 'examen-ciudadania-estados-unidos-65-20-preguntas-espanol'; end if;
end $$;
