  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es la forma de gobierno de los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS: República · República federal basada en la Constitución · Democracia representativa — En la entrevista se responde en inglés, por ejemplo: «Republic».', 0) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Democracia directa', false, 0), (v_q, 'Monarquía parlamentaria', false, 1), (v_q, 'Monarquía constitucional', false, 2), (v_q, 'República', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es la ley suprema de la nación?', 'single', 'Respuestas aceptadas por USCIS: La Constitución (de los EE. UU.) — En la entrevista se responde en inglés, por ejemplo: «The U.S. Constitution».', 1) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Los Artículos de la Confederación', false, 0), (v_q, 'La Declaración de Independencia', false, 1), (v_q, 'La Carta de Derechos', false, 2), (v_q, 'La Constitución de los EE. UU.', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione una cosa que hace la Constitución de los EE. UU.', 'single', 'Respuestas aceptadas por USCIS: Forma el gobierno · Define los poderes del gobierno · Define las partes del gobierno · Protege los derechos del pueblo — En la entrevista se responde en inglés, por ejemplo: «Defines powers of government».', 2) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Declara la independencia de Gran Bretaña', false, 0), (v_q, 'Elige al presidente', false, 1), (v_q, 'Recauda los impuestos federales', false, 2), (v_q, 'Define los poderes del gobierno', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'La Constitución de los EE. UU. comienza con las palabras “We the People” (Nosotros el Pueblo). ¿Qué significa “We the People”?', 'single', 'Respuestas aceptadas por USCIS: Autogobierno · Soberanía popular · Consentimiento de los gobernados · El pueblo debe gobernarse a sí mismo · (Ejemplo de) contrato social — En la entrevista se responde en inglés, por ejemplo: «Self-government».', 3) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Gobierno de la Corte Suprema', false, 0), (v_q, 'Gobierno del presidente', false, 1), (v_q, 'Autogobierno', true, 2), (v_q, 'Gobierno de los estados', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cómo se hacen cambios a la Constitución de los EE. UU.?', 'single', 'Respuestas aceptadas por USCIS: Enmiendas · El proceso de enmienda — En la entrevista se responde en inglés, por ejemplo: «Amendments».', 4) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Mediante enmiendas', true, 0), (v_q, 'Mediante fallos de la Corte Suprema', false, 1), (v_q, 'Mediante vetos presidenciales', false, 2), (v_q, 'Mediante órdenes ejecutivas', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Qué protege la Carta de Derechos (Bill of Rights)?', 'single', 'Respuestas aceptadas por USCIS: Los derechos (básicos) de los estadounidenses · Los derechos (básicos) de las personas que viven en los Estados Unidos — En la entrevista se responde en inglés, por ejemplo: «The basic rights of Americans».', 5) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Solo los poderes de los estados', false, 0), (v_q, 'Los derechos del gobierno federal', false, 1), (v_q, 'Los poderes del presidente', false, 2), (v_q, 'Los derechos básicos de los estadounidenses', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuántas enmiendas tiene la Constitución de los EE. UU.?', 'single', 'Respuestas aceptadas por USCIS: Veintisiete (27) — En la entrevista se responde en inglés, por ejemplo: «Twenty-seven (27)».', 6) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Treinta y tres (33)', false, 0), (v_q, 'Veintiuna (21)', false, 1), (v_q, 'Veintisiete (27)', true, 2), (v_q, 'Diez (10)', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por qué es importante la Declaración de Independencia?', 'single', 'Respuestas aceptadas por USCIS: Dice que Estados Unidos es libre del control británico. · Dice que todas las personas son creadas iguales. · Identifica derechos inherentes. · Identifica libertades individuales. — En la entrevista se responde en inglés, por ejemplo: «It says America is free from British control.».', 7) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Creó los tres poderes del gobierno.', false, 0), (v_q, 'Abolió la esclavitud.', false, 1), (v_q, 'Dice que Estados Unidos es libre del control británico.', true, 2), (v_q, 'Les dio a las mujeres el derecho al voto.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Qué documento fundacional dijo que las colonias americanas eran libres de Gran Bretaña?', 'single', 'Respuestas aceptadas por USCIS: La Declaración de Independencia — En la entrevista se responde en inglés, por ejemplo: «Declaration of Independence».', 8) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Constitución de los EE. UU.', false, 0), (v_q, 'Los Documentos Federalistas', false, 1), (v_q, 'La Declaración de Independencia', true, 2), (v_q, 'La Carta de Derechos', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione dos ideas importantes de la Declaración de Independencia y de la Constitución de los EE. UU.', 'single', 'Respuestas aceptadas por USCIS (hay que mencionar dos): Igualdad · Libertad · Contrato social · Derechos naturales · Gobierno limitado · Autogobierno — En la entrevista se responde en inglés, por ejemplo: «Equality and liberty».', 9) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Derechos naturales y gobierno ilimitado', false, 0), (v_q, 'Libertad y una religión oficial', false, 1), (v_q, 'Igualdad y monarquía', false, 2), (v_q, 'Igualdad y libertad', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿En qué documento fundacional están las palabras “Life, Liberty, and the pursuit of Happiness” (vida, libertad y la búsqueda de la felicidad)?', 'single', 'Respuestas aceptadas por USCIS: La Declaración de Independencia — En la entrevista se responde en inglés, por ejemplo: «Declaration of Independence».', 10) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Carta de Derechos', false, 0), (v_q, 'La Declaración de Independencia', true, 1), (v_q, 'La Constitución de los EE. UU.', false, 2), (v_q, 'La Proclamación de Emancipación', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es el sistema económico de los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS: Capitalismo · Economía de libre mercado — En la entrevista se responde en inglés, por ejemplo: «Capitalism».', 11) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Feudalismo', false, 0), (v_q, 'Capitalismo', true, 1), (v_q, 'Socialismo', false, 2), (v_q, 'Comunismo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Qué es el estado de derecho (rule of law)?', 'single', 'Respuestas aceptadas por USCIS: Todos deben obedecer la ley. · Los líderes deben obedecer la ley. · El gobierno debe obedecer la ley. · Nadie está por encima de la ley. — En la entrevista se responde en inglés, por ejemplo: «No one is above the law.».', 12) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Cada estado puede ignorar la ley federal.', false, 0), (v_q, 'Nadie está por encima de la ley.', true, 1), (v_q, 'El presidente hace todas las leyes.', false, 2), (v_q, 'Solo los ciudadanos deben obedecer la ley.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Muchos documentos influyeron en la Constitución de los EE. UU. Mencione uno.', 'single', 'Respuestas aceptadas por USCIS: La Declaración de Independencia · Los Artículos de la Confederación · Los Documentos Federalistas · Los Documentos Antifederalistas · La Declaración de Derechos de Virginia · Las Órdenes Fundamentales de Connecticut · El Pacto del Mayflower · La Gran Ley de la Paz de los iroqueses — En la entrevista se responde en inglés, por ejemplo: «Articles of Confederation».', 13) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Doctrina Monroe', false, 0), (v_q, 'El Discurso de Gettysburg', false, 1), (v_q, 'La Proclamación de Emancipación', false, 2), (v_q, 'Los Artículos de la Confederación', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Hay tres poderes (ramas) del gobierno. ¿Por qué?', 'single', 'Respuestas aceptadas por USCIS: Para que una parte no se vuelva demasiado poderosa · Pesos y contrapesos · Separación de poderes — En la entrevista se responde en inglés, por ejemplo: «So one part does not become too powerful».', 14) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Para que una parte no se vuelva demasiado poderosa', true, 0), (v_q, 'Para que los estados puedan ignorar las leyes federales', false, 1), (v_q, 'Para que el presidente controle los tribunales', false, 2), (v_q, 'Para aprobar las leyes más rápido', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione los tres poderes (ramas) del gobierno.', 'single', 'Respuestas aceptadas por USCIS: Legislativo, ejecutivo y judicial · El Congreso, el presidente y los tribunales — En la entrevista se responde en inglés, por ejemplo: «Legislative, executive, and judicial».', 15) returning id into v_q;
