  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿De qué poder (rama) del gobierno está a cargo el presidente de los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS: El Poder Ejecutivo — En la entrevista se responde en inglés, por ejemplo: «Executive branch».', 16) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'El Poder Judicial', false, 0), (v_q, 'El Poder Ejecutivo', true, 1), (v_q, 'Los gobiernos estatales', false, 2), (v_q, 'El Poder Legislativo', false, 3);
