  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por qué los representantes federales tienen mandatos más cortos que los senadores federales?', 'single', 'Respuestas aceptadas por USCIS: Para seguir más de cerca la opinión pública — En la entrevista se responde en inglés, por ejemplo: «To more closely follow public opinion».', 24) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Porque son menos importantes', false, 0), (v_q, 'Para seguir más de cerca la opinión pública', true, 1), (v_q, 'Porque los nombra el presidente', false, 2), (v_q, 'Para ahorrar dinero en elecciones', false, 3);
