  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por qué cada estado tiene dos senadores?', 'single', 'Respuestas aceptadas por USCIS: Representación igualitaria (para los estados pequeños) · El Gran Compromiso (Compromiso de Connecticut) — En la entrevista se responde en inglés, por ejemplo: «Equal representation (for small states)».', 26) returning id into v_q;
