  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuáles son dos cargos a nivel de Gabinete?', 'single', 'Respuestas aceptadas por USCIS (hay que mencionar dos): Fiscal General · Secretario de Agricultura · Secretario de Comercio · Secretario de Educación · Secretario de Energía · Secretario de Salud y Servicios Humanos · Secretario de Seguridad Nacional · Secretario de Vivienda y Desarrollo Urbano · Secretario del Interior · Secretario de Trabajo · Secretario de Estado · Secretario de Transporte · Secretario del Tesoro · Secretario de Asuntos de Veteranos · Secretario de Guerra (Defensa) · Vicepresidente · Administrador de la Agencia de Protección Ambiental · Administrador de la Agencia Federal de Pequeños Negocios · Director de la Agencia Central de Inteligencia · Director de la Oficina de Administración y Presupuesto · Director de Inteligencia Nacional · Representante Comercial de los Estados Unidos — En la entrevista se responde en inglés, por ejemplo: «Secretary of State and Attorney General».', 45) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Secretario de Estado y Fiscal General', true, 0), (v_q, 'Presidente de la Cámara de Representantes y Secretario de Estado', false, 1), (v_q, 'Presidente de la Corte Suprema y Fiscal General', false, 2), (v_q, 'Líder de la mayoría del Senado y Secretario de Trabajo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por qué es importante el Colegio Electoral?', 'single', 'Respuestas aceptadas por USCIS: Decide quién es elegido presidente. · Es un compromiso entre la elección popular del presidente y la selección por el Congreso. — En la entrevista se responde en inglés, por ejemplo: «It decides who is elected president.».', 46) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Elige a los jueces de la Corte Suprema.', false, 0), (v_q, 'Cuenta los votos para el Congreso.', false, 1), (v_q, 'Elabora el presupuesto federal.', false, 2), (v_q, 'Decide quién es elegido presidente.', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es una parte del Poder Judicial?', 'single', 'Respuestas aceptadas por USCIS: La Corte Suprema · Los tribunales federales — En la entrevista se responde en inglés, por ejemplo: «Supreme Court».', 47) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Corte Suprema', true, 0), (v_q, 'El Senado', false, 1), (v_q, 'El Colegio Electoral', false, 2), (v_q, 'El Gabinete', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Qué hace el Poder Judicial?', 'single', 'Respuestas aceptadas por USCIS: Revisa las leyes · Explica las leyes · Resuelve disputas (desacuerdos) sobre la ley · Decide si una ley va en contra de la Constitución (de los EE. UU.) — En la entrevista se responde en inglés, por ejemplo: «Decides if a law goes against the U.S. Constitution».', 48) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Firma proyectos de ley', false, 0), (v_q, 'Decide si una ley va en contra de la Constitución', true, 1), (v_q, 'Redacta nuevas leyes', false, 2), (v_q, 'Declara la guerra', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es el tribunal más alto de los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS: La Corte Suprema — En la entrevista se responde en inglés, por ejemplo: «Supreme Court».', 49) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Corte Suprema', true, 0), (v_q, 'El Congreso', false, 1), (v_q, 'El Tribunal de Distrito', false, 2), (v_q, 'El Tribunal de Apelaciones', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuántos puestos (jueces) tiene la Corte Suprema?', 'single', 'Respuestas aceptadas por USCIS: Nueve (9) — En la entrevista se responde en inglés, por ejemplo: «Nine (9)».', 50) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Doce (12)', false, 0), (v_q, 'Siete (7)', false, 1), (v_q, 'Nueve (9)', true, 2), (v_q, 'Cincuenta (50)', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuántos jueces de la Corte Suprema se necesitan normalmente para decidir un caso?', 'single', 'Respuestas aceptadas por USCIS: Cinco (5) — En la entrevista se responde en inglés, por ejemplo: «Five (5)».', 51) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Nueve (9)', false, 0), (v_q, 'Cinco (5)', true, 1), (v_q, 'Tres (3)', false, 2), (v_q, 'Siete (7)', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por cuánto tiempo sirven los jueces de la Corte Suprema?', 'single', 'Respuestas aceptadas por USCIS: De por vida · Nombramiento vitalicio · (Hasta) su jubilación — En la entrevista se responde en inglés, por ejemplo: «For life».', 52) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Cuatro (4) años', false, 0), (v_q, 'De por vida', true, 1), (v_q, 'Diez (10) años', false, 2), (v_q, 'Hasta que se elige un nuevo presidente', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Los jueces de la Corte Suprema sirven de por vida. ¿Por qué?', 'single', 'Respuestas aceptadas por USCIS: Para ser independientes (de la política) · Para limitar la influencia (política) externa — En la entrevista se responde en inglés, por ejemplo: «To be independent (of politics)».', 53) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Porque la Constitución no los menciona', false, 0), (v_q, 'Porque los elige el pueblo', false, 1), (v_q, 'Para que el presidente pueda controlarlos', false, 2), (v_q, 'Para ser independientes de la política', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es el nombre del presidente actual de la Corte Suprema de los Estados Unidos (Chief Justice)?', 'single', 'Vigente a octubre de 2026: John Roberts. Los funcionarios pueden cambiar; verifica en uscis.gov/citizenship/testupdates antes de tu entrevista. — En la entrevista se responde en inglés, por ejemplo: «John Roberts».', 54) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'John Roberts', true, 0), (v_q, 'Amy Coney Barrett', false, 1), (v_q, 'Sonia Sotomayor', false, 2), (v_q, 'Clarence Thomas', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione un poder que corresponde solo al gobierno federal.', 'single', 'Respuestas aceptadas por USCIS: Imprimir billetes · Acuñar monedas · Declarar la guerra · Crear un ejército · Celebrar tratados · Establecer la política exterior — En la entrevista se responde en inglés, por ejemplo: «Print paper money».', 55) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Otorgar licencias de conducir', false, 0), (v_q, 'Proveer escuelas y educación', false, 1), (v_q, 'Imprimir billetes', true, 2), (v_q, 'Aprobar la zonificación y el uso del suelo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione un poder que corresponde solo a los estados.', 'single', 'Respuestas aceptadas por USCIS: Proveer escuelas y educación · Proveer protección (policía) · Proveer seguridad (departamentos de bomberos) · Otorgar licencias de conducir · Aprobar la zonificación y el uso del suelo — En la entrevista se responde en inglés, por ejemplo: «Give a driver''s license».', 56) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Imprimir billetes', false, 0), (v_q, 'Celebrar tratados', false, 1), (v_q, 'Declarar la guerra', false, 2), (v_q, 'Otorgar licencias de conducir', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es el propósito de la Enmienda 10?', 'single', 'Respuestas aceptadas por USCIS: (Establece que) los poderes que no se otorgan al gobierno federal pertenecen a los estados o al pueblo. — En la entrevista se responde en inglés, por ejemplo: «Powers not given to the federal government belong to the states or to the people.».', 57) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Les da a las mujeres el derecho al voto.', false, 0), (v_q, 'Limita al presidente a dos mandatos.', false, 1), (v_q, 'Garantiza la libertad de expresión.', false, 2), (v_q, 'Los poderes que no se otorgan al gobierno federal pertenecen a los estados o al pueblo.', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Hay cuatro enmiendas a la Constitución sobre quién puede votar. Describa una de ellas.', 'single', 'Respuestas aceptadas por USCIS: Los ciudadanos de dieciocho (18) años en adelante (pueden votar). · No se tiene que pagar (un impuesto electoral) para votar. · Cualquier ciudadano puede votar. (Mujeres y hombres pueden votar.) · Un ciudadano varón de cualquier raza (puede votar). — En la entrevista se responde en inglés, por ejemplo: «Citizens eighteen (18) and older can vote.».', 58) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Los ciudadanos deben aprobar un examen para votar.', false, 0), (v_q, 'Solo los propietarios pueden votar.', false, 1), (v_q, 'Solo los hombres pueden votar.', false, 2), (v_q, 'Los ciudadanos de 18 años en adelante pueden votar.', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Quién puede votar en elecciones federales, postularse para un cargo federal y servir como jurado en los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS: Los ciudadanos · Los ciudadanos de los Estados Unidos · Los ciudadanos estadounidenses — En la entrevista se responde en inglés, por ejemplo: «U.S. citizens».', 59) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Los ciudadanos de los Estados Unidos', true, 0), (v_q, 'Cualquier persona que pague impuestos', false, 1), (v_q, 'Cualquier persona que viva en los Estados Unidos', false, 2), (v_q, 'Los residentes permanentes legales', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuáles son tres derechos de todas las personas que viven en los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS (hay que mencionar tres): Libertad de expresión · Libertad de palabra · Libertad de reunión · Libertad de peticionar al gobierno · Libertad de religión · El derecho a portar armas — En la entrevista se responde en inglés, por ejemplo: «Freedom of speech, freedom of religion, and freedom of assembly».', 60) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Libertad de palabra, libertad de religión y libertad de reunión', true, 0), (v_q, 'Libertad de religión, derecho a ser jurado y derecho a portar armas', false, 1), (v_q, 'Libertad de palabra, derecho al voto y libertad de religión', false, 2), (v_q, 'Derecho a postularse a un cargo federal, libertad de palabra y libertad de reunión', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿A qué le demostramos lealtad cuando decimos el Juramento a la Bandera (Pledge of Allegiance)?', 'single', 'Respuestas aceptadas por USCIS: A los Estados Unidos · A la bandera — En la entrevista se responde en inglés, por ejemplo: «The United States».', 61) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Al presidente', false, 0), (v_q, 'A los Estados Unidos', true, 1), (v_q, 'A los autores de la Constitución', false, 2), (v_q, 'Al estado donde uno vive', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione dos promesas que hacen los nuevos ciudadanos en el Juramento de Lealtad (Oath of Allegiance).', 'single', 'Respuestas aceptadas por USCIS (hay que mencionar dos): Renunciar a la lealtad a otros países · Defender la Constitución (de los EE. UU.) · Obedecer las leyes de los Estados Unidos · Servir en las fuerzas armadas (si es necesario) · Servir a la nación (ayudarla, hacer trabajos importantes para ella) (si es necesario) · Ser leal a los Estados Unidos — En la entrevista se responde en inglés, por ejemplo: «Give up loyalty to other countries and obey the laws of the United States».', 62) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Renunciar a la lealtad a otros países y obedecer las leyes de los Estados Unidos', true, 0), (v_q, 'Obedecer las leyes de los Estados Unidos y vivir 10 años en el país', false, 1), (v_q, 'Renunciar a la lealtad a otros países y votar en todas las elecciones', false, 2), (v_q, 'Defender la Constitución y afiliarse a un partido político', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cómo pueden las personas convertirse en ciudadanos de los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS: Nacer en los Estados Unidos, según las condiciones de la Enmienda 14 · Naturalizarse · Derivar la ciudadanía (según las condiciones que fija el Congreso) — En la entrevista se responde en inglés, por ejemplo: «Naturalize».', 63) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Comprando una propiedad en los Estados Unidos', false, 0), (v_q, 'Pagando impuestos federales durante cinco años', false, 1), (v_q, 'Naturalizándose', true, 2), (v_q, 'Inscribiéndose en el Servicio Selectivo', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuáles son dos ejemplos de participación cívica en los Estados Unidos?', 'single', 'Respuestas aceptadas por USCIS (hay que mencionar dos): Votar · Postularse para un cargo · Afiliarse a un partido político · Ayudar en una campaña · Unirse a un grupo cívico · Unirse a un grupo comunitario · Darle su opinión (sobre un tema) a un funcionario electo · Contactar a los funcionarios electos · Apoyar u oponerse a un tema o política · Escribir a un periódico — En la entrevista se responde en inglés, por ejemplo: «Vote and join a civic group».', 64) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Votar y unirse a un grupo cívico', true, 0), (v_q, 'Unirse a un grupo comunitario y negarse a ser jurado', false, 1), (v_q, 'Postularse para un cargo y evitar pagar impuestos', false, 2), (v_q, 'Votar y pagar un impuesto electoral', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuál es una manera en que los estadounidenses pueden servir a su país?', 'single', 'Respuestas aceptadas por USCIS: Votar · Pagar impuestos · Obedecer la ley · Servir en las fuerzas armadas · Postularse para un cargo · Trabajar para el gobierno local, estatal o federal — En la entrevista se responde en inglés, por ejemplo: «Pay taxes».', 65) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Pagar impuestos', true, 0), (v_q, 'Viajar al extranjero', false, 1), (v_q, 'Aprender un segundo idioma', false, 2), (v_q, 'Comprar productos estadounidenses', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por qué es importante pagar impuestos federales?', 'single', 'Respuestas aceptadas por USCIS: Lo exige la ley · Todas las personas pagan para financiar el gobierno federal · Lo exige la Constitución (Enmienda 16) · Deber cívico — En la entrevista se responde en inglés, por ejemplo: «Required by law».', 66) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Para obtener un pasaporte estadounidense', false, 0), (v_q, 'Porque lo exige la ley', true, 1), (v_q, 'Porque solo los ciudadanos deben pagarlos', false, 2), (v_q, 'Para poder votar', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Es importante que todos los hombres de 18 a 25 años se inscriban en el Servicio Selectivo. Mencione una razón.', 'single', 'Respuestas aceptadas por USCIS: Lo exige la ley · Deber cívico · Hace que el reclutamiento sea justo, si fuera necesario — En la entrevista se responde en inglés, por ejemplo: «Required by law».', 67) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Porque todos los hombres deben servir en las fuerzas armadas', false, 0), (v_q, 'Para poder votar', false, 1), (v_q, 'Porque lo exige la ley', true, 2), (v_q, 'Para obtener la licencia de conducir', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Los colonos vinieron a América por muchas razones. Mencione una.', 'single', 'Respuestas aceptadas por USCIS: Libertad · Libertad política · Libertad religiosa · Oportunidades económicas · Escapar de la persecución — En la entrevista se responde en inglés, por ejemplo: «Religious freedom».', 68) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Para estar más cerca del rey británico', false, 0), (v_q, 'Para buscar oro en California', false, 1), (v_q, 'Libertad religiosa', true, 2), (v_q, 'Para servir al rey británico', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Quiénes vivían en América antes de que llegaran los europeos?', 'single', 'Respuestas aceptadas por USCIS: Los indígenas americanos · Los nativos americanos — En la entrevista se responde en inglés, por ejemplo: «American Indians».', 69) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Los españoles', false, 0), (v_q, 'Los indígenas americanos (nativos americanos)', true, 1), (v_q, 'Los africanos', false, 2), (v_q, 'Los británicos', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Qué grupo de personas fue llevado a la fuerza y vendido como esclavos?', 'single', 'Respuestas aceptadas por USCIS: Los africanos · Las personas de África — En la entrevista se responde en inglés, por ejemplo: «Africans».', 70) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Los africanos', true, 0), (v_q, 'Los franceses', false, 1), (v_q, 'Los británicos', false, 2), (v_q, 'Los indígenas americanos', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿En qué guerra lucharon los estadounidenses para ganar la independencia de Gran Bretaña?', 'single', 'Respuestas aceptadas por USCIS: La Revolución Americana · La Guerra Revolucionaria (estadounidense) · La Guerra de Independencia (de los Estados Unidos) — En la entrevista se responde en inglés, por ejemplo: «The American Revolution».', 71) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Primera Guerra Mundial', false, 0), (v_q, 'La Revolución Americana', true, 1), (v_q, 'La Guerra de 1812', false, 2), (v_q, 'La Guerra Civil', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Mencione una razón por la que los estadounidenses declararon la independencia de Gran Bretaña.', 'single', 'Respuestas aceptadas por USCIS: Impuestos altos · Impuestos sin representación · Los soldados británicos se alojaban en las casas de los estadounidenses (alojamiento, acuartelamiento) · No tenían autogobierno · La Masacre de Boston · El Motín del Té de Boston (Ley del Té) · La Ley del Timbre · La Ley del Azúcar · Las Leyes Townshend · Las Leyes Intolerables (Coercitivas) — En la entrevista se responde en inglés, por ejemplo: «Taxation without representation».', 72) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'El ataque a Pearl Harbor', false, 0), (v_q, 'Impuestos sin representación', true, 1), (v_q, 'La Proclamación de Emancipación', false, 2), (v_q, 'La Compra de Luisiana', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Quién escribió la Declaración de Independencia?', 'single', 'Respuestas aceptadas por USCIS: (Thomas) Jefferson — En la entrevista se responde en inglés, por ejemplo: «Thomas Jefferson».', 73) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Abraham Lincoln', false, 0), (v_q, 'George Washington', false, 1), (v_q, 'James Madison', false, 2), (v_q, 'Thomas Jefferson', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Cuándo se adoptó la Declaración de Independencia?', 'single', 'Respuestas aceptadas por USCIS: El 4 de julio de 1776 — En la entrevista se responde en inglés, por ejemplo: «July 4, 1776».', 74) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'El 17 de septiembre de 1787', false, 0), (v_q, 'El 4 de julio de 1789', false, 1), (v_q, 'El 25 de diciembre de 1776', false, 2), (v_q, 'El 4 de julio de 1776', true, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'La Revolución Americana tuvo muchos acontecimientos importantes. Mencione uno.', 'single', 'Respuestas aceptadas por USCIS: (La Batalla de) Bunker Hill · La Declaración de Independencia · Washington cruza el río Delaware (Batalla de Trenton) · (La Batalla de) Saratoga · (El campamento de) Valley Forge · (La Batalla de) Yorktown (rendición británica en Yorktown) — En la entrevista se responde en inglés, por ejemplo: «Battle of Yorktown».', 75) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Batalla de Fort Sumter', false, 0), (v_q, 'Pearl Harbor', false, 1), (v_q, 'La Batalla de Yorktown', true, 2), (v_q, 'La Batalla de Gettysburg', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Había 13 estados originales. Mencione cinco.', 'single', 'Respuestas aceptadas por USCIS: Nueva Hampshire · Massachusetts · Rhode Island · Connecticut · Nueva York · Nueva Jersey · Pensilvania · Delaware · Maryland · Virginia · Carolina del Norte · Carolina del Sur · Georgia — En la entrevista se responde en inglés, por ejemplo: «New York, New Jersey, Pennsylvania, Virginia, and Georgia».', 76) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Massachusetts, Connecticut, Ohio, Delaware y Virginia', false, 0), (v_q, 'Nueva York, Nueva Jersey, Pensilvania, Virginia y Georgia', true, 1), (v_q, 'Nueva York, Florida, Virginia, Georgia y Maryland', false, 2), (v_q, 'Texas, Georgia, Virginia, Maryland y Delaware', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Qué documento fundacional se escribió en 1787?', 'single', 'Respuestas aceptadas por USCIS: La Constitución (de los EE. UU.) — En la entrevista se responde en inglés, por ejemplo: «The U.S. Constitution».', 77) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'La Declaración de Independencia', false, 0), (v_q, 'La Carta de Derechos', false, 1), (v_q, 'La Constitución de los EE. UU.', true, 2), (v_q, 'La Proclamación de Emancipación', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Los Documentos Federalistas (Federalist Papers) apoyaron la aprobación de la Constitución de los EE. UU. Mencione a uno de sus autores.', 'single', 'Respuestas aceptadas por USCIS: (James) Madison · (Alexander) Hamilton · (John) Jay · Publius — En la entrevista se responde en inglés, por ejemplo: «James Madison».', 78) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'George Washington', false, 0), (v_q, 'Thomas Jefferson', false, 1), (v_q, 'James Madison', true, 2), (v_q, 'Benjamin Franklin', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, '¿Por qué fueron importantes los Documentos Federalistas?', 'single', 'Respuestas aceptadas por USCIS: Ayudaron a la gente a entender la Constitución (de los EE. UU.). · Apoyaron la aprobación de la Constitución (de los EE. UU.). — En la entrevista se responde en inglés, por ejemplo: «They helped people understand the U.S. Constitution.».', 79) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Crearon la Corte Suprema.', false, 0), (v_q, 'Ayudaron a la gente a entender la Constitución.', true, 1), (v_q, 'Declararon la independencia de Gran Bretaña.', false, 2), (v_q, 'Pusieron fin a la Guerra Civil.', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'Benjamin Franklin es famoso por muchas cosas. Mencione una.', 'single', 'Respuestas aceptadas por USCIS: Fundó las primeras bibliotecas públicas gratuitas · Primer director general del Servicio Postal de los Estados Unidos · Ayudó a redactar la Declaración de Independencia · Inventor · Diplomático de los EE. UU. — En la entrevista se responde en inglés, por ejemplo: «First Postmaster General of the United States».', 80) returning id into v_q;
  insert into options (question_id, body, is_correct, "order") values (v_q, 'Primer director general del Servicio Postal de los EE. UU.', true, 0), (v_q, 'Redactó la Proclamación de Emancipación', false, 1), (v_q, 'Tercer presidente de los Estados Unidos', false, 2), (v_q, 'Primer presidente de los Estados Unidos', false, 3);
  insert into questions (quiz_id, body, type, explanation, "order") values (v_quiz, 'George Washington es famoso por muchas cosas. Mencione una.', 'single', 'Respuestas aceptadas por USCIS: “Padre de nuestra patria” · Primer presidente de los Estados Unidos · General del Ejército Continental · Presidente de la Convención Constitucional — En la entrevista se responde en inglés, por ejemplo: «First president of the United States».', 81) returning id into v_q;
